async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(apiEndpoint(path), { ...init, cache: "no-store" });
  const payload = await response.json().catch(() => ({})) as T & { error?: string };
  if (!response.ok) throw new Error(payload.error ?? "请求失败");
  return payload;
}

function formatDate(value?: string | null): string { if (!value) return "—"; return new Intl.DateTimeFormat("zh-CN", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value)); }
function formatValue(value: Cell): string { if (value === null || value === undefined) return "—"; if (typeof value === "number") return new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 2 }).format(value); return String(value); }
function chartTypeName(type: FlintSpec["chartSpec"]["chartType"]): string { return type === "Bar Chart" ? "柱状图" : type === "Area Chart" ? "面积图" : "折线图"; }
function rowsForEvidence(evidence: EvidenceRecord | null): Array<Record<string, Cell>> { if (evidence?.job?.previewData?.rows) return evidence.job.previewData.rows; return evidence?.revision.flintSpec.data.values ?? []; }

function InteractiveChart({ rows, spec }: { rows: Array<Record<string, Cell>>; spec: FlintSpec }) {
  const [activePoint, setActivePoint] = useState<string | null>(null);
  const xField = spec.chartSpec.encodings.x?.field;
  const yField = spec.chartSpec.encodings.y?.field;
  const colorField = spec.chartSpec.encodings.color?.field;
  const chartRows = useMemo(() => rows.filter((row) => xField && yField && typeof row[yField] === "number"), [rows, xField, yField]);
  const xValues = useMemo(() => [...new Set(chartRows.map((row) => String(xField ? row[xField] ?? "" : "")))], [chartRows, xField]);
  const seriesValues = useMemo(() => colorField ? [...new Set(chartRows.map((row) => String(row[colorField] ?? "")))] : [""], [chartRows, colorField]);
  const values = chartRows.map((row) => Number(yField ? row[yField] : 0));
  if (!xField || !yField || chartRows.length === 0) return <div className="chart-empty">无可绘制数据</div>;
  const width = 900; const height = 360; const left = 70; const top = 28; const right = 22; const bottom = 56; const plotWidth = width - left - right; const plotHeight = height - top - bottom; const min = Math.min(...values, 0); const max = Math.max(...values, 0); const range = max - min || 1; const colors = ["#1f1d3d", "#ff3d8b", "#1ea64a", "#000000"]; const xPosition = (value: string) => xValues.length <= 1 ? plotWidth / 2 : xValues.indexOf(value) * plotWidth / (xValues.length - 1); const yPosition = (value: number) => plotHeight - ((value - min) / range) * plotHeight; const baseline = top + yPosition(Math.min(0, max));
  return <div className="chart-visual" aria-label={`${spec.chartSpec.title}图表预览`}><svg className="chart-svg" viewBox={`0 0 ${width} ${height}`} role="img"><line x1={left} y1={top + plotHeight} x2={left + plotWidth} y2={top + plotHeight} className="chart-axis" /><line x1={left} y1={top} x2={left} y2={top + plotHeight} className="chart-axis" />{[0, 0.33, 0.66, 1].map((step) => <g key={step}><line x1={left} y1={top + plotHeight * step} x2={left + plotWidth} y2={top + plotHeight * step} className="chart-grid" /><text x={left - 10} y={top + plotHeight * step + 4} textAnchor="end">{formatValue(max - (max - min) * step)}</text></g>)}{xValues.map((value) => <text key={value} x={left + xPosition(value)} y={top + plotHeight + 25} textAnchor="middle">{value}</text>)}{seriesValues.map((seriesValue, seriesIndex) => { const points = chartRows.filter((row) => !colorField || String(row[colorField] ?? "") === seriesValue).sort((a, b) => xValues.indexOf(String(a[xField] ?? "")) - xValues.indexOf(String(b[xField] ?? ""))); const path = points.map((row, index) => `${index === 0 ? "M" : "L"}${left + xPosition(String(row[xField] ?? ""))},${top + yPosition(Number(row[yField]))}`).join(" "); const areaPath = `${path} L ${left + xPosition(String(points[points.length - 1]?.[xField] ?? ""))},${baseline} L ${left + xPosition(String(points[0]?.[xField] ?? ""))},${baseline} Z`; return <g key={seriesValue || "default"}>{spec.chartSpec.chartType === "Area Chart" && <path d={areaPath} fill={colors[seriesIndex % colors.length]} opacity="0.12" />}{spec.chartSpec.chartType === "Bar Chart" ? points.map((row, index) => { const value = Number(row[yField]); const slot = plotWidth / Math.max(xValues.length * seriesValues.length, 1); const barWidth = Math.max(8, slot * 0.68); const x = left + xPosition(String(row[xField] ?? "")) - ((seriesValues.length - 1) * barWidth) / 2 + seriesIndex * barWidth; const y = top + yPosition(Math.max(value, 0)); const key = `${seriesValue}-${index}`; return <rect key={key} tabIndex={0} role="button" aria-label={`${String(row[xField] ?? "")}: ${formatValue(row[yField])}`} x={x - barWidth / 2} y={Math.min(y, baseline)} width={Math.max(3, barWidth - 2)} height={Math.max(2, Math.abs(baseline - y))} fill={colors[seriesIndex % colors.length]} opacity={activePoint === key ? 1 : 0.78} onMouseEnter={() => setActivePoint(key)} onFocus={() => setActivePoint(key)} />; }) : <><path d={path} fill="none" stroke={colors[seriesIndex % colors.length]} strokeWidth="3" />{points.map((row, index) => { const key = `${seriesValue}-${index}`; return <circle key={key} tabIndex={0} role="button" aria-label={`${String(row[xField] ?? "")}: ${formatValue(row[yField])}`} cx={left + xPosition(String(row[xField] ?? ""))} cy={top + yPosition(Number(row[yField]))} r={activePoint === key ? 7 : 4.5} fill={colors[seriesIndex % colors.length]} onMouseEnter={() => setActivePoint(key)} onFocus={() => setActivePoint(key)} />; })}</>}</g>; })}</svg><div className="chart-readout">{activePoint ? "数据点已聚焦" : "选择数据点"}</div></div>;
}

function Pipeline({ job }: { job: GenerationJob }) { const currentIndex = pipelineStages.indexOf(job.status); return <div className="pipeline" aria-label="生成周期状态">{pipelineStages.map((stage, index) => <div className={`${index < currentIndex || job.status === "succeeded" ? "done" : ""} ${stage === job.status ? "current" : ""}`} key={stage}><span>{index + 1}</span><strong>{statusLabels[stage]}</strong></div>)}</div>; }

export default function Home() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null); const [projects, setProjects] = useState<Project[]>([]); const [projectId, setProjectId] = useState<string | null>(null); const [conversations, setConversations] = useState<Conversation[]>([]); const [conversationId, setConversationId] = useState<string | null>(null); const [messages, setMessages] = useState<ConversationMessage[]>([]); const [assets, setAssets] = useState<Asset[]>([]); const [selectedAssetId, setSelectedAssetId] = useState<string | null>(null); const [metric, setMetric] = useState<MetricDefinition | null>(null); const [brief, setBrief] = useState<AnalysisBrief | null>(null); const [memory, setMemory] = useState<MemoryContext>({ project: [], workspace: [], conflicts: [] }); const [evidence, setEvidence] = useState<EvidenceRecord[]>([]); const [job, setJob] = useState<GenerationJob | null>(null); const [theme, setTheme] = useState("economist"); const [composer, setComposer] = useState(""); const [projectName, setProjectName] = useState(""); const [metricForm, setMetricForm] = useState({ name: "销售额", meaning: "客户订单的销售金额总和。", formula: "sum(销售额)", unit: "人民币", timeRule: "按自然月聚合", filterRule: "" }); const [editor, setEditor] = useState({ title: "", chartType: "Line Chart" as FlintSpec["chartSpec"]["chartType"], xField: "", yField: "", seriesField: "" }); const [projectMenuOpen, setProjectMenuOpen] = useState(false); const [conversationMenuOpen, setConversationMenuOpen] = useState(false); const [showProjectModal, setShowProjectModal] = useState(false); const [showMetricModal, setShowMetricModal] = useState(false); const [showEditor, setShowEditor] = useState(false); const [showTrace, setShowTrace] = useState(false); const [leftRailOpen, setLeftRailOpen] = useState(true); const [rightRailOpen, setRightRailOpen] = useState(true); const [mobileInspectorOpen, setMobileInspectorOpen] = useState(false); const [isBooting, setIsBooting] = useState(true); const [isLoadingProject, setIsLoadingProject] = useState(false); const [isSending, setIsSending] = useState(false); const [isUploading, setIsUploading] = useState(false); const [isGenerating, setIsGenerating] = useState(false); const [isSavingEditor, setIsSavingEditor] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null); const fileInputRef = useRef<HTMLInputElement>(null);

  const project = useMemo(() => projects.find((item) => item.id === projectId) ?? null, [projects, projectId]); const selectedAsset = useMemo(() => assets.find((asset) => asset.id === selectedAssetId) ?? assets[0] ?? null, [assets, selectedAssetId]); const selectedConversation = useMemo(() => conversations.find((item) => item.id === conversationId) ?? null, [conversations, conversationId]); const activeEvidence = useMemo(() => evidence.find((item) => item.block.conversationId === conversationId) ?? null, [evidence, conversationId]); const activeRevision = activeEvidence?.revision ?? null; const activeSpec = activeEvidence?.revision.flintSpec ?? job?.flintSpec ?? null; const activeRows = rowsForEvidence(activeEvidence); const qualityWarnings = useMemo(() => selectedAsset?.latestSnapshot?.schema.filter((column) => column.nullCount > 0).map((column) => ({ code: "NULL_VALUES", message: `${column.name} 有 ${column.nullCount.toLocaleString()} 个缺失值，生成未将缺失月份静默补为 0。`, severity: "warning" as const, field: column.name })) ?? [], [selectedAsset]); const isJobActive = Boolean(job && !["succeeded", "failed"].includes(job.status)); const hasSnapshot = Boolean(selectedAsset?.latestSnapshot && selectedAsset.status === "ready"); const hasMetric = metric?.status === "confirmed"; const canGenerate = Boolean(projectId && hasSnapshot && hasMetric && !isJobActive && !isGenerating); const availableFields = activeSpec ? Object.keys(activeSpec.data.values[0] ?? {}) : [];

  const loadProjects = useCallback(async () => { const payload = await apiFetch<{ workspace: Workspace | null; projects: Project[] }>("/api/v1/projects", { headers: devHeaders }); setWorkspace(payload.workspace); setProjects(payload.projects); return payload; }, []);
  const loadEvidence = useCallback(async (nextProjectId: string) => { const payload = await apiFetch<{ evidence: EvidenceRecord[] }>(`/api/v1/projects/${nextProjectId}/evidence-blocks`, { headers: devHeaders }); setEvidence(payload.evidence); return payload.evidence; }, []);
  const loadConversations = useCallback(async (nextProjectId: string) => { const payload = await apiFetch<{ conversations: Conversation[] }>(`/api/v1/projects/${nextProjectId}/conversations`, { headers: devHeaders }); setConversations(payload.conversations); return payload.conversations; }, []);

  useEffect(() => { let cancelled = false; async function boot() { try { setIsBooting(true); const bootstrap = await apiFetch<{ workspace: Workspace; project: Project }>("/api/v1/dev/bootstrap", { method: "POST", headers: jsonHeaders, body: "{}" }); const payload = await loadProjects(); if (cancelled) return; const remembered = window.localStorage.getItem("langreport-project-id"); setProjectId(payload.projects.find((item) => item.id === remembered)?.id ?? bootstrap.project.id ?? payload.projects[0]?.id ?? null); } catch (bootError) { if (!cancelled) setError(bootError instanceof Error ? bootError.message : "无法连接 LangReport API"); } finally { if (!cancelled) setIsBooting(false); } } void boot(); return () => { cancelled = true; }; }, [loadProjects]);
  useEffect(() => { if (!projectId) return; window.localStorage.setItem("langreport-project-id", projectId); let cancelled = false; async function loadProject() { try { setIsLoadingProject(true); setAssets([]); setConversations([]); setMessages([]); setEvidence([]); setMetric(null); setBrief(null); setJob(null); const [assetPayload, conversationPayload, metricPayload, briefPayload, memoryPayload, evidencePayload, themePayload] = await Promise.all([apiFetch<{ assets: Asset[] }>(`/api/v1/projects/${projectId}/data-assets`, { headers: devHeaders }), apiFetch<{ conversations: Conversation[] }>(`/api/v1/projects/${projectId}/conversations`, { headers: devHeaders }), apiFetch<{ definition: MetricDefinition | null }>(`/api/v1/projects/${projectId}/metric-definition`, { headers: devHeaders }), apiFetch<{ brief: AnalysisBrief | null }>(`/api/v1/projects/${projectId}/analysis-brief`, { headers: devHeaders }), apiFetch<{ memory: MemoryContext }>(`/api/v1/projects/${projectId}/memories`, { headers: devHeaders }), apiFetch<{ evidence: EvidenceRecord[] }>(`/api/v1/projects/${projectId}/evidence-blocks`, { headers: devHeaders }), apiFetch<{ theme: { preset: string } }>(`/api/v1/projects/${projectId}/theme`, { headers: devHeaders })]); if (cancelled) return; setAssets(assetPayload.assets); setSelectedAssetId(assetPayload.assets[0]?.id ?? null); setConversations(conversationPayload.conversations); setMetric(metricPayload.definition); setBrief(briefPayload.brief); setMemory(memoryPayload.memory); setEvidence(evidencePayload.evidence); setTheme(themePayload.theme.preset); const rememberedConversation = window.localStorage.getItem(`langreport-conversation-${projectId}`); setConversationId(conversationPayload.conversations.find((item) => item.id === rememberedConversation)?.id ?? conversationPayload.conversations[0]?.id ?? null); const latest = evidencePayload.evidence[0]; if (latest?.job && !["succeeded", "failed"].includes(latest.job.status)) setJob(latest.job); } catch (loadError) { if (!cancelled) setError(loadError instanceof Error ? loadError.message : "无法读取项目数据"); } finally { if (!cancelled) setIsLoadingProject(false); } } void loadProject(); return () => { cancelled = true; }; }, [projectId]);
  useEffect(() => { if (!conversationId) { setMessages([]); return; } window.localStorage.setItem(`langreport-conversation-${projectId}`, conversationId); let cancelled = false; void apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { headers: devHeaders }).then((payload) => { if (!cancelled) setMessages(payload.messages); }).catch((loadError) => { if (!cancelled) setError(loadError instanceof Error ? loadError.message : "无法读取对话"); }); return () => { cancelled = true; }; }, [conversationId, projectId]);
  useEffect(() => { if (job && job.conversationId !== conversationId) setJob(null); }, [conversationId, job]);
  useEffect(() => { if (!job?.id || !isJobActive) return; let cancelled = false; const poll = async () => { try { const payload = await apiFetch<{ job: GenerationJob; revision: GenerationJob["revision"] }>(`/api/v1/generation-jobs/${job.id}`, { headers: devHeaders }); if (cancelled) return; setJob({ ...payload.job, revision: payload.revision }); if (payload.job.status === "succeeded" && projectId) { await Promise.all([loadEvidence(projectId), loadConversations(projectId)]); if (conversationId) { const messagePayload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { headers: devHeaders }); if (!cancelled) setMessages(messagePayload.messages); } setNotice(payload.job.operation === "edit" ? "新的草稿版本已保存。" : "证据模块已生成。"); } } catch (pollError) { if (!cancelled) setError(pollError instanceof Error ? pollError.message : "无法读取生成状态"); } }; void poll(); const interval = window.setInterval(() => { void poll(); }, 900); return () => { cancelled = true; window.clearInterval(interval); }; }, [conversationId, isJobActive, job?.id, loadConversations, loadEvidence, projectId]);

  async function createConversation(): Promise<string | null> { if (!projectId) return null; try { const payload = await apiFetch<{ conversation: Conversation }>(`/api/v1/projects/${projectId}/conversations`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ title: "新的分析对话" }) }); setConversations((current) => [payload.conversation, ...current]); setConversationId(payload.conversation.id); return payload.conversation.id; } catch (createError) { setError(createError instanceof Error ? createError.message : "无法创建对话"); return null; } }
  async function createProject() { if (!projectName.trim()) return; try { const payload = await apiFetch<{ project: Project }>("/api/v1/projects", { method: "POST", headers: jsonHeaders, body: JSON.stringify({ name: projectName.trim() }) }); const nextProjects = await loadProjects(); setProjects(nextProjects.projects); setProjectId(payload.project.id); setProjectName(""); setShowProjectModal(false); setNotice(`已创建项目「${payload.project.name}」。`); } catch (createError) { setError(createError instanceof Error ? createError.message : "无法创建项目"); } }
  async function sendMessage() { const content = composer.trim(); if (!content || !projectId || isSending) return; setIsSending(true); setError(null); try { const nextConversationId = conversationId ?? await createConversation(); if (!nextConversationId) return; const payload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${nextConversationId}/messages`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ content }) }); setMessages((current) => [...current, ...payload.messages]); setComposer(""); setConversations(await loadConversations(projectId)); } catch (sendError) { setError(sendError instanceof Error ? sendError.message : "消息保存失败"); } finally { setIsSending(false); } }
  async function confirmMetric() { if (!projectId || !metricForm.name.trim()) return; try { const payload = await apiFetch<{ definition: MetricDefinition }>(`/api/v1/projects/${projectId}/metric-definitions`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ ...metricForm, filterRule: metricForm.filterRule || undefined, conversationId: conversationId ?? undefined }) }); setMetric(payload.definition); setShowMetricModal(false); setNotice(`已确认「${payload.definition.name}」口径 v${payload.definition.version}。`); if (conversationId) { const messagePayload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ content: `确认指标口径：${payload.definition.name} = ${payload.definition.formula}`, assistantContent: `已确认指标口径 v${payload.definition.version}。` }) }); setMessages((current) => [...current, ...messagePayload.messages]); } } catch (metricError) { setError(metricError instanceof Error ? metricError.message : "无法保存指标口径"); } }
  async function uploadFile(file: File) { if (!projectId) return; setIsUploading(true); setError(null); try { const formData = new FormData(); formData.append("file", file); const payload = await apiFetch<{ asset: Asset }>(`/api/v1/projects/${projectId}/data-assets/upload`, { method: "POST", headers: devHeaders, body: formData }); setAssets((current) => [payload.asset, ...current]); setSelectedAssetId(payload.asset.id); setNotice(`已生成数据快照 v${payload.asset.latestSnapshot?.version ?? 1}。`); } catch (uploadError) { setError(uploadError instanceof Error ? uploadError.message : "文件上传失败"); } finally { setIsUploading(false); if (fileInputRef.current) fileInputRef.current.value = ""; } }
  async function pasteData(content: string, name: string) { if (!projectId || !content.trim()) return; setIsUploading(true); setError(null); try { const payload = await apiFetch<{ asset: Asset }>(`/api/v1/projects/${projectId}/data-assets/paste`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ name, content }) }); setAssets((current) => [payload.asset, ...current]); setSelectedAssetId(payload.asset.id); setNotice(`已保存「${payload.asset.name}」并创建数据快照。`); } catch (pasteError) { setError(pasteError instanceof Error ? pasteError.message : "粘贴数据失败"); } finally { setIsUploading(false); } }
  async function generateEvidence() { if (!projectId || !selectedAsset?.latestSnapshot || !metric || selectedAsset.status !== "ready" || isJobActive || isGenerating) return; setIsGenerating(true); setError(null); setNotice(null); try { const nextConversationId = conversationId ?? await createConversation(); if (!nextConversationId) return; const prompt = composer.trim() || "按月份展示各区域销售额和同比变化，并指出数据质量限制"; const payload = await apiFetch<{ job: GenerationJob }>(`/api/v1/projects/${projectId}/generation-jobs`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ conversationId: nextConversationId, dataAssetId: selectedAsset.id, prompt, renderer: "vega-lite" }) }); setJob({ ...payload.job, revision: null }); setComposer(""); } catch (generationError) { setError(generationError instanceof Error ? generationError.message : "无法创建生成周期"); } finally { setIsGenerating(false); } }
  function openEditor() { if (!activeEvidence || activeRevision?.status === "approved" || activeRevision?.status === "archived") return; const spec = activeEvidence.revision.flintSpec; setEditor({ title: spec.chartSpec.title, chartType: spec.chartSpec.chartType, xField: spec.chartSpec.encodings.x?.field ?? "", yField: spec.chartSpec.encodings.y?.field ?? "", seriesField: spec.chartSpec.encodings.color?.field ?? "" }); setShowEditor(true); }
  async function saveEditor() { if (!activeEvidence || !activeRevision || !editor.title.trim() || isSavingEditor) return; setIsSavingEditor(true); setError(null); try { const encodings: FlintSpec["chartSpec"]["encodings"] = { x: { field: editor.xField, type: activeEvidence.revision.flintSpec.chartSpec.encodings.x?.type ?? "nominal" }, y: { field: editor.yField, type: "quantitative" } }; if (editor.seriesField) encodings.color = { field: editor.seriesField, type: "nominal" }; const payload = await apiFetch<{ job: GenerationJob }>(`/api/v1/chart-artifacts/${activeEvidence.artifact.id}/revisions`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ operation: "edit", baseRevisionId: activeRevision.id, patch: { title: editor.title.trim(), chartType: editor.chartType, encodings } }) }); setJob({ ...payload.job, revision: null }); setShowEditor(false); setNotice("编辑任务已排队。"); } catch (editError) { setError(editError instanceof Error ? editError.message : "无法创建新的版本"); } finally { setIsSavingEditor(false); } }
  async function transitionRevision(action: "submit" | "approve" | "request-changes") { if (!activeRevision) return; try { const payload = await apiFetch<{ revision: Revision }>(`/api/v1/chart-revisions/${activeRevision.id}/${action}`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ expectedStatus: activeRevision.status, note: action === "request-changes" ? "请补充图表说明或处理数据质量警告" : undefined }) }); setEvidence((current) => current.map((item) => item.revision.id === payload.revision.id ? { ...item, revision: payload.revision, block: { ...item.block, status: payload.revision.status } } : item)); setNotice(`版本 R${payload.revision.revision} 已更新为 ${revisionLabels[payload.revision.status]}`); } catch (transitionError) { setError(transitionError instanceof Error ? transitionError.message : "无法更新审核状态"); } }

  return <div className={`app-shell ${leftRailOpen ? "left-open" : "left-collapsed"} ${rightRailOpen ? "right-open" : "right-collapsed"}`} onClick={() => { setProjectMenuOpen(false); setConversationMenuOpen(false); }}>
    <header className="topbar" onClick={(event) => event.stopPropagation()}>
      <div className="brand-lockup"><span className="brand-mark">L/</span><span className="brand-name">LangReport</span></div>
      <div className="top-selectors">
        <div className="selector project-selector"><button type="button" className="selector-button" aria-expanded={projectMenuOpen} onClick={() => { setProjectMenuOpen((open) => !open); setConversationMenuOpen(false); }}><span className="selector-icon">P</span><span className="selector-copy"><span className="eyebrow">项目</span><strong>{project?.name ?? (isBooting ? "连接中" : "选择项目")}</strong><small>{workspace?.name ?? "本地工作区"}</small></span><span className="selector-chevron">⌄</span></button>{projectMenuOpen && <div className="selector-menu"><span className="menu-kicker">项目列表</span>{projects.map((item) => <button type="button" key={item.id} className={`menu-item ${item.id === projectId ? "current" : ""}`} onClick={() => { setProjectId(item.id); setProjectMenuOpen(false); }}><strong>{item.name}</strong><small>{item.id === projectId ? "当前项目" : "项目"}</small></button>)}<button type="button" className="menu-create" onClick={() => { setShowProjectModal(true); setProjectMenuOpen(false); }}>＋ 新建项目</button></div>}</div>
        <div className="selector conversation-selector"><button type="button" className="selector-button" aria-expanded={conversationMenuOpen} onClick={() => { setConversationMenuOpen((open) => !open); setProjectMenuOpen(false); }}><span className="selector-icon">C</span><span className="selector-copy"><span className="eyebrow">对话</span><strong>{selectedConversation?.title ?? "新的分析对话"}</strong><small>{conversations.length} 条记录</small></span><span className="selector-chevron">⌄</span></button>{conversationMenuOpen && <div className="selector-menu"><span className="menu-kicker">对话列表</span>{conversations.map((item) => <button type="button" key={item.id} className={`menu-item ${item.id === conversationId ? "current" : ""}`} onClick={() => { setConversationId(item.id); setConversationMenuOpen(false); }}><strong>{item.title}</strong><small>{formatDate(item.updatedAt)}</small></button>)}<button type="button" className="menu-create" onClick={() => { void createConversation(); setConversationMenuOpen(false); }}>＋ 新建对话</button></div>}</div>
      </div>
      <div className="topbar-actions"><span className={`connection-dot ${error ? "attention" : ""}`} aria-label={error ? "有错误" : "接口正常"} /><button type="button" className="rail-toggle desktop-only" aria-label={leftRailOpen ? "隐藏对话历史" : "显示对话历史"} onClick={() => setLeftRailOpen((open) => !open)}>{leftRailOpen ? "‹" : "›"}</button><button type="button" className="rail-toggle desktop-only" aria-label={rightRailOpen ? "隐藏依据面板" : "显示依据面板"} onClick={() => setRightRailOpen((open) => !open)}>{rightRailOpen ? "›" : "‹"}</button><button type="button" className="mobile-inspector-button" aria-label="打开项目依据" onClick={() => setMobileInspectorOpen(true)}>☷</button></div>
    </header>

    <div className="workspace-grid">
      <aside className="history-rail" aria-label="对话历史"><div className="rail-head"><div><div className="eyebrow">历史</div><h2>对话</h2></div><button type="button" className="icon-button small-icon" aria-label="新建对话" onClick={() => void createConversation()}>＋</button></div><div className="history-list">{isLoadingProject ? <div className="rail-empty">载入中</div> : conversations.length === 0 ? <div className="rail-empty">—</div> : conversations.map((item) => { const conversationEvidence = evidence.find((record) => record.block.conversationId === item.id); return <button type="button" key={item.id} className={`history-item ${item.id === conversationId ? "current" : ""}`} onClick={() => setConversationId(item.id)}><strong>{item.title}</strong><small>{conversationEvidence ? `R${conversationEvidence.revision.revision} · ${revisionLabels[conversationEvidence.revision.status]}` : "暂无版本"}</small><div className="history-meta"><span>{formatDate(item.updatedAt)}</span><span>↗</span></div></button>; })}</div><div className="rail-divider" /><div className="eyebrow rail-context-title">项目</div><div className="rail-context"><div><span>数据文件</span><strong>{assets.length.toString().padStart(2, "0")}</strong></div><div><span>证据模块</span><strong>{evidence.length.toString().padStart(2, "0")}</strong></div><div><span>指标</span><strong>{hasMetric ? "正常" : "—"}</strong></div><div><span>主题</span><strong>{theme}</strong></div></div><div className="rail-divider" /><div className="rail-source"><div className="eyebrow">数据</div><label className="secondary-button upload-button"><input ref={fileInputRef} type="file" accept=".csv,.xlsx,.xls,.json" disabled={isUploading || isBooting} onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadFile(file); }} />{isUploading ? "处理中" : "导入文件"}</label><button type="button" className="text-button" onClick={() => void pasteData(sampleCsv, "sales-sample.csv")} disabled={isUploading || isBooting}>使用示例</button></div></aside>

      <main className="workspace-main"><div className="canvas-header"><div className="canvas-title"><div className="eyebrow">{activeEvidence ? `证据模块 / R${activeRevision?.revision}` : isJobActive ? "生成周期" : "分析"}</div><h1>{activeEvidence?.block.title ?? selectedConversation?.title ?? "新的分析"}</h1></div><div className="canvas-header-actions"><div className="stage-rail"><span className={`stage-step ${hasSnapshot ? "complete" : ""}`}><i />数据</span><span className={`stage-step ${hasMetric ? "complete" : ""}`}><i />指标</span><span className={`stage-step ${activeEvidence ? "complete" : ""}`}><i />证据</span></div><button type="button" className="inspector-trigger mobile-only" onClick={() => setMobileInspectorOpen(true)}>依据</button></div></div>{error && <div className="alert error-alert" role="alert"><strong>错误</strong><span>{error}</span><button type="button" onClick={() => setError(null)}>×</button></div>}{notice && <div className="alert notice-alert" role="status"><span>{notice}</span><button type="button" onClick={() => setNotice(null)}>×</button></div>}
        <section className={`workbench-canvas ${activeEvidence ? "has-evidence" : "no-evidence"}`} aria-label="证据工作区">{isLoadingProject && <div className="canvas-state"><span className="state-mark pulse-mark" /><strong>载入中</strong></div>}{!isLoadingProject && job && isJobActive && <div className="job-stage"><div className="job-stage-head"><div><div className="eyebrow">生成周期</div><h2>{statusLabels[job.status] ?? job.status}</h2></div><span className="status-dot" /></div><Pipeline job={job} /></div>}{!isLoadingProject && job?.status === "failed" && <div className="failure-stage"><div className="eyebrow">生成失败</div><strong>{job.errorCode ?? "生成失败"}</strong><p>{job.errorMessage ?? "生成失败"}</p><button type="button" className="secondary-button" onClick={() => setError(null)}>关闭</button></div>}{!isLoadingProject && activeEvidence && <div className="evidence-canvas"><div className="evidence-head"><div><div className="eyebrow">图表产物</div><h2>{activeEvidence.block.title}</h2></div><span className={`result-status ${activeEvidence.revision.status}`}><i />{revisionLabels[activeEvidence.revision.status]}</span></div><div className="chart-stage"><InteractiveChart rows={activeRows} spec={activeEvidence.revision.flintSpec} /></div><div className="finding"><span className="eyebrow">发现</span><p>{activeEvidence.block.finding}</p></div><div className="evidence-proof"><div><span>数据快照</span><strong>{activeEvidence.block.snapshotId.slice(0, 8)}</strong></div><div><span>指标</span><strong>{metric?.name ?? "—"}</strong></div><div><span>主题</span><strong>{activeEvidence.revision.flintSpec.theme} · {activeEvidence.revision.flintSpec.themeVersion}</strong></div><div><span>版本</span><strong>R{activeEvidence.revision.revision}</strong></div></div>{(qualityWarnings.length > 0 || activeEvidence.block.qualityWarnings.length > 0) && <div className="quality-warning" role="status"><strong>质量</strong><span>{[...qualityWarnings, ...activeEvidence.block.qualityWarnings].slice(0, 3).map((warning) => warning.message).join("；")}</span></div>}<div className="result-actions"><button type="button" className="primary-button" onClick={openEditor} disabled={activeEvidence.revision.status === "approved" || activeEvidence.revision.status === "archived"}>编辑图表 <span>↗</span></button><button type="button" className="secondary-button" onClick={() => setShowTrace((open) => !open)}>{showTrace ? "收起依据" : "查看依据"}</button>{activeEvidence.revision.status === "draft" && <button type="button" className="secondary-button" onClick={() => void transitionRevision("submit")}>提交审核</button>}{activeEvidence.revision.status === "in_review" && <><button type="button" className="primary-button" onClick={() => void transitionRevision("approve")}>批准版本 <span>↗</span></button><button type="button" className="secondary-button" onClick={() => void transitionRevision("request-changes")}>要求修改</button></>}</div>{showTrace && <div className="trace-grid"><div><span>变换计划</span><strong>{activeEvidence.revision.transformPlan.steps?.length ?? 0} 步</strong><small>{activeEvidence.revision.transformPlan.rationale ?? "—"}</small></div><div><span>字段血缘</span><strong>{activeEvidence.revision.fieldLineage.length} 个输出</strong><small>{activeEvidence.revision.fieldLineage.map((line) => `${line.outputColumn} ← ${line.sourceColumns.join(" + ")}`).join(" · ") || "—"}</small></div><div><span>校验</span><strong>{activeEvidence.revision.validation.valid ? "4 / 4 通过" : "失败"}</strong><small>{activeEvidence.revision.validation.issues.length ? activeEvidence.revision.validation.issues.map((issue) => issue.message).join("；") : "结构 · 语义 · 字段 · 视觉"}</small></div><div><span>不可变</span><strong>快照固定</strong><small>R{activeEvidence.revision.revision} 已锁定：{activeEvidence.revision.status === "approved" ? "是" : "否"}</small></div></div>}</div>}{!isLoadingProject && !activeEvidence && !isJobActive && <div className="canvas-empty"><div className="empty-orbit"><span>+</span><i /><b /></div><div className="empty-copy"><div className="eyebrow">工作区</div><h2>{hasSnapshot && hasMetric ? "准备生成" : hasSnapshot ? "需要指标" : "需要数据"}</h2><div className="readiness-grid"><span className={hasSnapshot ? "ready" : "pending"}><i />数据快照</span><span className={hasMetric ? "ready" : "pending"}><i />指标口径</span><span className={conversationId ? "ready" : "pending"}><i />对话</span></div><div className="empty-actions">{!hasSnapshot && <button type="button" className="primary-button" onClick={() => fileInputRef.current?.click()}>导入数据 ↗</button>}{hasSnapshot && !hasMetric && <button type="button" className="primary-button" onClick={() => setShowMetricModal(true)}>确认指标 ↗</button>}{hasSnapshot && hasMetric && <button type="button" className="primary-button" onClick={() => void generateEvidence()} disabled={!canGenerate}>{isGenerating ? "创建中" : "生成证据 ↗"}</button>}</div></div></div>}</section>{messages.length > 0 && <details className="conversation-log"><summary><span className="eyebrow">对话</span><strong>{messages.length} 条消息</strong><span>⌄</span></summary><div className="conversation-messages">{messages.map((message) => <div className={`conversation-message ${message.role === "user" ? "from-user" : "from-system"}`} key={message.id}><span>{message.role === "user" ? "我" : "AI"}</span><p>{message.content}</p><time>{formatDate(message.createdAt)}</time></div>)}</div></details>}<div className="composer-wrap"><div className="composer"><textarea value={composer} onChange={(event) => setComposer(event.target.value)} onKeyDown={(event) => { if ((event.metaKey || event.ctrlKey) && event.key === "Enter") void sendMessage(); }} aria-label="继续对话" placeholder="输入分析问题…" disabled={isSending || isJobActive} /><div className="composer-bottom"><div className="composer-meta"><span>{selectedAsset?.latestSnapshot ? `数据快照 v${selectedAsset.latestSnapshot.version}` : "暂无快照"}</span><span>{hasMetric ? "指标已确认" : "指标待确认"}</span></div><div className="composer-actions"><button type="button" className="secondary-button composer-send" onClick={() => void sendMessage()} disabled={!composer.trim() || isSending || isJobActive}>{isSending ? "保存中" : "发送"}</button><button type="button" className="primary-button composer-generate" onClick={() => void generateEvidence()} disabled={!canGenerate}>{isGenerating ? "创建中" : isJobActive ? `${statusLabels[job?.status ?? "queued"]}…` : "生成证据 ↗"}</button></div></div></div><div className="prompt-row"><button type="button" className="prompt-chip" onClick={() => setComposer("按月份展示各区域销售额")}>区域销售 / 月度</button><button type="button" className="prompt-chip" onClick={() => setComposer("对比各区域同比变化")}>区域同比</button></div></div></main>

      <aside className={`context-rail ${mobileInspectorOpen ? "mobile-open" : ""}`} aria-label="项目证据上下文"><div className="context-header"><div><div className="eyebrow">依据</div><h2>证据上下文</h2></div><button type="button" className="context-close mobile-only" aria-label="关闭依据面板" onClick={() => setMobileInspectorOpen(false)}>×</button></div><details open><summary><strong>数据快照</strong><span>{hasSnapshot ? "✓" : "＋"}</span></summary><div className="context-content">{selectedAsset?.latestSnapshot ? <><div className="context-row"><span>数据文件</span><strong>{selectedAsset.name}</strong></div><div className="context-row"><span>快照</span><strong>v{selectedAsset.latestSnapshot.version} · {selectedAsset.latestSnapshot.rowCount.toLocaleString()} 行</strong></div><div className="context-row"><span>字段</span><strong>{selectedAsset.latestSnapshot.columnCount}</strong></div><div className="context-quality">{qualityWarnings.length ? `${qualityWarnings.length} 个字段存在缺失值` : "数据完整"}</div><div className="context-data-list">{selectedAsset.latestSnapshot.schema.slice(0, 6).map((column) => <div key={column.name}><span>{column.name}</span><small>{column.inferredType} · {column.distinctCount} 个唯一值</small></div>)}</div></> : <div className="context-empty"><strong>未导入数据</strong><button type="button" onClick={() => fileInputRef.current?.click()}>导入数据</button></div>}</div></details><details><summary><strong>分析简报与指标</strong><span>{hasMetric ? "✓" : "＋"}</span></summary><div className="context-content">{brief && <div className="context-note">{brief.businessQuestion}</div>}{metric ? <><div className="context-row"><span>指标</span><strong>{metric.name} · v{metric.version}</strong></div><div className="context-note">{metric.formula} · {metric.unit} · {metric.timeRule}</div></> : <button type="button" className="context-cta" onClick={() => setShowMetricModal(true)}>确认指标口径 <span>↗</span></button>}</div></details><details><summary><strong>项目记忆</strong><span>{memory.project.length + memory.workspace.length ? "✓" : "—"}</span></summary><div className="context-content">{memory.project.length + memory.workspace.length === 0 ? <div className="context-empty">—</div> : [...memory.project, ...memory.workspace].slice(0, 5).map((record) => <div className="memory-line" key={record.id}><i />{record.statement}</div>)}{memory.conflicts.length > 0 && <div className="context-warning">{memory.conflicts.length} 个冲突</div>}</div></details><details><summary><strong>主题与版本</strong><span>{activeRevision ? "✓" : "—"}</span></summary><div className="context-content">{activeRevision ? <><div className="context-row"><span>主题</span><strong>{activeRevision.flintSpec.theme} · {activeRevision.flintSpec.themeVersion}</strong></div><div className="context-row"><span>版本</span><strong>R{activeRevision.revision} · {revisionLabels[activeRevision.status]}</strong></div><div className="context-row"><span>父版本</span><strong>{activeRevision.parentRevisionId ? activeRevision.parentRevisionId.slice(0, 8) : "初始"}</strong></div></> : <div className="context-empty">—</div>}</div></details></aside>
    </div>

    {showProjectModal && <div className="modal-backdrop" role="presentation" onClick={() => setShowProjectModal(false)}><section className="modal-dialog small-modal" role="dialog" aria-modal="true" aria-labelledby="project-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head lilac-head"><div><div className="eyebrow">新建项目</div><h2 id="project-modal-title">创建项目</h2></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowProjectModal(false)}>×</button></div><div className="modal-body"><label className="field-label"><span>项目名称</span><input autoFocus value={projectName} onChange={(event) => setProjectName(event.target.value)} placeholder="例如：海岚消费洞察" onKeyDown={(event) => { if (event.key === "Enter") void createProject(); }} /></label></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={() => setShowProjectModal(false)}>取消</button><button type="button" className="primary-button" onClick={() => void createProject()} disabled={!projectName.trim()}>创建项目 ↗</button></div></section></div>}
    {showMetricModal && <div className="modal-backdrop" role="presentation" onClick={() => setShowMetricModal(false)}><section className="modal-dialog small-modal" role="dialog" aria-modal="true" aria-labelledby="metric-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head pink-head"><div><div className="eyebrow">指标口径</div><h2 id="metric-modal-title">确认指标口径</h2></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowMetricModal(false)}>×</button></div><div className="modal-body form-grid"><label className="field-label"><span>名称</span><input value={metricForm.name} onChange={(event) => setMetricForm((current) => ({ ...current, name: event.target.value }))} /></label><label className="field-label"><span>含义</span><textarea value={metricForm.meaning} onChange={(event) => setMetricForm((current) => ({ ...current, meaning: event.target.value }))} /></label><label className="field-label"><span>公式</span><input value={metricForm.formula} onChange={(event) => setMetricForm((current) => ({ ...current, formula: event.target.value }))} /></label><div className="form-row"><label className="field-label"><span>单位</span><input value={metricForm.unit} onChange={(event) => setMetricForm((current) => ({ ...current, unit: event.target.value }))} /></label><label className="field-label"><span>时间规则</span><input value={metricForm.timeRule} onChange={(event) => setMetricForm((current) => ({ ...current, timeRule: event.target.value }))} /></label></div><label className="field-label"><span>筛选 / 限制</span><input value={metricForm.filterRule} onChange={(event) => setMetricForm((current) => ({ ...current, filterRule: event.target.value }))} placeholder="可选" /></label></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={() => setShowMetricModal(false)}>取消</button><button type="button" className="primary-button" onClick={() => void confirmMetric()} disabled={!metricForm.name.trim()}>确认并保存 ↗</button></div></section></div>}
    {showEditor && activeEvidence && activeSpec && <div className="modal-backdrop" role="presentation" onClick={() => setShowEditor(false)}><section className="modal-dialog editor-modal" role="dialog" aria-modal="true" aria-labelledby="editor-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head cream-head"><div><div className="eyebrow">图表产物 / R{activeRevision?.revision} / 新草稿</div><h2 id="editor-modal-title">编辑图表</h2></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowEditor(false)}>×</button></div><div className="editor-body"><div className="editor-preview"><div className="editor-preview-head"><div><strong>{editor.title}</strong><small>{chartTypeName(editor.chartType)} · 草稿</small></div><span className="revision-chip">R{(activeRevision?.revision ?? 0) + 1} 草稿</span></div><InteractiveChart rows={activeRows} spec={{ ...activeSpec, chartSpec: { ...activeSpec.chartSpec, title: editor.title, chartType: editor.chartType, encodings: { x: { field: editor.xField }, y: { field: editor.yField }, ...(editor.seriesField ? { color: { field: editor.seriesField } } : {}) } } }} /><div className="editor-preview-foot"><span>数据快照 v{selectedAsset?.latestSnapshot?.version ?? "—"}</span><span>血缘 · {activeRevision?.fieldLineage.length ?? 0}</span></div></div><div className="editor-controls"><div className="control-group"><h3>图表结构</h3><label className="field-label"><span>图表类型</span><select value={editor.chartType} onChange={(event) => setEditor((current) => ({ ...current, chartType: event.target.value as FlintSpec["chartSpec"]["chartType"] }))}><option value="Line Chart">折线图</option><option value="Bar Chart">柱状图</option><option value="Area Chart">面积图</option></select></label><label className="field-label"><span>横轴</span><select value={editor.xField} onChange={(event) => setEditor((current) => ({ ...current, xField: event.target.value }))}>{availableFields.map((field) => <option value={field} key={field}>{field}</option>)}</select></label><label className="field-label"><span>纵轴</span><select value={editor.yField} onChange={(event) => setEditor((current) => ({ ...current, yField: event.target.value }))}>{availableFields.map((field) => <option value={field} key={field}>{field}</option>)}</select></label><label className="field-label"><span>系列 / 颜色</span><select value={editor.seriesField} onChange={(event) => setEditor((current) => ({ ...current, seriesField: event.target.value }))}><option value="">不分系列</option>{availableFields.filter((field) => field !== editor.yField).map((field) => <option value={field} key={field}>{field}</option>)}</select></label></div><div className="control-group"><h3>标题</h3><label className="field-label"><span>标题</span><input value={editor.title} onChange={(event) => setEditor((current) => ({ ...current, title: event.target.value }))} /></label><div className="logic-note"><strong>{editor.xField !== activeSpec.chartSpec.encodings.x?.field || editor.yField !== activeSpec.chartSpec.encodings.y?.field || editor.seriesField !== (activeSpec.chartSpec.encodings.color?.field ?? "") ? "数据逻辑已变更" : "仅视觉变化"}</strong></div></div></div></div><div className="modal-footer"><p>仅追加 · 已批准版本只读</p><div><button type="button" className="secondary-button" onClick={() => setShowEditor(false)}>取消</button><button type="button" className="primary-button" onClick={() => void saveEditor()} disabled={isSavingEditor || !editor.title.trim() || !editor.xField || !editor.yField}>{isSavingEditor ? "保存中" : "保存为新版本 ↗"}</button></div></div></section></div>}
  </div>;
}
